// Step 2: Data Structure Validation for Legal Document Analysis
// This code validates incoming form data and ensures it matches our expected schema

// First, let's extract the incoming data from the webhook
// Based on Step 1 findings, form data is nested in the 'body' property
const incomingData = $input.first().json;

// Initialize our validation results object
const validationResult = {
  isValid: false,
  errors: [],
  validatedData: null,
  processingTimestamp: new Date().toISOString()
};

// Check if the basic structure exists
// We expect data to be in incomingData.body based on Step 1 findings
if (!incomingData.body) {
  validationResult.errors.push("Missing form data structure. Expected 'body' property not found.");
  return [{ json: validationResult }];
}

const formData = incomingData.body;

// Validate required fields according to Form_Output_Documentation.md
// Required fields: clientName and attorneyName
const requiredFields = ['clientName', 'attorneyName'];

for (const field of requiredFields) {
  if (!formData[field]) {
    validationResult.errors.push(`Missing required field: ${field}`);
  } else if (typeof formData[field] !== 'string') {
    validationResult.errors.push(`Field ${field} must be a string`);
  } else if (formData[field].trim().length === 0) {
    validationResult.errors.push(`Field ${field} cannot be empty`);
  }
}

// Validate optional field (caseReference) if present
if (formData.caseReference && typeof formData.caseReference !== 'string') {
  validationResult.errors.push("Field caseReference must be a string");
}

// If we have errors, return them immediately
if (validationResult.errors.length > 0) {
  validationResult.isValid = false;
  return [{ json: validationResult }];
}

// If validation passes, prepare clean data structure
const cleanData = {
  clientName: formData.clientName.trim(),
  caseReference: formData.caseReference ? formData.caseReference.trim() : '',
  attorneyName: formData.attorneyName.trim()
};

// Set success status and return validated data
validationResult.isValid = true;
validationResult.validatedData = cleanData;
validationResult.message = "Form data validation successful";

return [{ json: validationResult }];

// Step 3: Intake Form Data Processing
// This node structures the validated intake form data into a standardized format
// Based on the established pattern from the proposed workflow's caseInfo structure

const validationData = $input.first().json;

// Only process if validation was successful
if (!validationData.isValid) {
  // Pass through validation errors unchanged
  return [{ json: validationData }];
}

// Extract the clean validated data
const validatedFields = validationData.validatedData;

// Structure the intake form data into standardized JSON format
// Following the caseInfo pattern from the proposed workflow
const structuredIntakeData = {
  caseInfo: {
    clientName: validatedFields.clientName,
    caseReference: validatedFields.caseReference || `CASE-${new Date().toISOString().split('T')[0]}`,
    attorneyName: validatedFields.attorneyName,
    processingDate: new Date().toISOString()
  },
  dataProcessingStatus: {
    intakeFormProcessed: true,
    structuredAt: new Date().toISOString(),
    dataQuality: 'validated'
  },
  nextStage: 'document-processing'
};

// Return the structured data with success metadata
return [{
  json: {
    isValid: true,
    structuredData: structuredIntakeData,
    processingTimestamp: validationData.processingTimestamp,
    message: 'Intake form data successfully structured for processing'
  }
}];

// Extract all binary files (intakeForm + caseDocument*) from Webhook
const intakeResult = $input.first().json;
const structuredData = intakeResult.structuredData; // passed along
const webhookItems = $items('Webhook1'); // get ALL files from Webhook node

const outputs = [];
try {
  const intakeResult = $input.first().json;
  const structuredData = intakeResult.structuredData;
  const webhookItems = $items('Webhook1');

  for (const item of webhookItems) {
    const binary = item.binary || {};

  for (const [key, bin] of Object.entries(binary)) {
    if (!bin?.data) continue;

    const isIntake = key === 'intakeForm';

    outputs.push({
      json: {
        documentType: isIntake ? 'intakeForm' : 'caseDocument',
        documentId: isIntake ? 'intake-form' : key,
        meta: {
          fileName: bin.fileName,
          mimeType: bin.mimeType,
          fileSize: bin.fileSize
        },
        structuredData
      },
      binary: {
        data: bin
      }
    });
  }
  }
  return outputs;
} catch (error) {
  console.error('Error processing binary files:', error);
  return [{ json: { error: error.message } }];
}

// In Filter PDFs
const inputItems = $input.all();
const pdfItems = inputItems.filter(item => {
  const mimeType = item.json.meta?.mimeType;
  if (!mimeType) {
    console.warn('Item missing mimeType:', item.json);
    return false;
  }
  return mimeType === 'application/pdf';
});

if (pdfItems.length === 0) {
  throw new Error('No PDF files found to process');
}

return pdfItems;

// Generate debug package with workflow data for UI visibility
const debugPackage = {
  timestamp: new Date().toISOString(),
  workflow: '1_intake',
  inputItemCount: $input.all().length,
  nodeExecutionData: $input.all(),
  executionInfo: {
    nodeId: 'Generate & Send Debug Package',
    processingTime: new Date().toISOString(),
    dataTypes: $input.all().map(item => ({
      hasJson: !!item.json,
      hasBinary: !!item.binary,
      jsonKeys: item.json ? Object.keys(item.json) : [],
      binaryKeys: item.binary ? Object.keys(item.binary) : []
    }))
  }
};

// Return both debug output (visible in Node Output → JSON) and pass-through data
return [
  // First output: Debug data (visible in UI)
  { 
    json: { 
      debug: debugPackage,
      message: 'Debug package generated - check Node Output → JSON tab'
    } 
  },
  // Remaining outputs: Pass through original data for workflow continuation
  ...$input.all()
];
